package real

import "strings"

// concealedMarkers are substrings of platform clipboard format names that password managers and other
// tools set to ask clipboard tools not to record a copy: the three macOS nspasteboard conventions
// (ConcealedType, TransientType, AutoGeneratedType, the same set the 1.x app checks) and the Windows
// exclude-from-history flag.
var concealedMarkers = []string{
	"concealed",
	"transienttype",
	"autogeneratedtype",
	"excludeclipboardcontent",
}

// isConcealedClipboard reports whether any format name carries a concealed marker.
func isConcealedClipboard(formats []string) bool {
	for _, format := range formats {
		lower := strings.ToLower(format)
		for _, marker := range concealedMarkers {
			if strings.Contains(lower, marker) {
				return true
			}
		}
	}
	return false
}
